content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 20px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  background-color: var(--card-bg);
  padding: 20px 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
}

.header h1 {
  font-size: 1.5rem;
  color: var(--text-main);
}

.total-amount {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--primary-color);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

.card {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.section-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-main);
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 8px;
}

.chart-container {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 280px;
}

.list-container {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 250px;
  overflow-y: auto;
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background-color: var(--bg-color);
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  border-left: 5px solid transparent;
}

.expense-item:hover {
  background-color: var(--border-color);
}

.expense-item.active {
  background-color: #e0e7ff;
  border-left-color: var(--primary-color);
}

.detail-card {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid var(--border-color);
}

.detail-card h3 {
  font-size: 1.1rem;
  color: var(--primary-color);
}

.detail-card p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  align-self: flex-start;
}

.btn:hover {
  background-color: var(--primary-hover);
}

export interface ExpenseItem {
  id: string;
  category: string;
  amount: number;
  color: string;
  memo: string;
}

export interface AppProps {}

import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from 'recharts';
import { ExpenseItem } from './types';
import './index.css';

interface ExpenseChartProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (item: ExpenseItem) => void;
}

export default function ExpenseChart({ items = [], selectedId, onSelect }: ExpenseChartProps) {
  return (
    <div className="chart-container">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={items}
            dataKey="amount"
            nameKey="category"
            cx="50%"
            cy="50%"
            outerRadius={90}
            innerRadius={40}
            paddingAngle={2}
            onClick={(entry) => {
              if (entry) {
                onSelect(entry as unknown as ExpenseItem);
              }
            }}
            cursor="pointer"
          >
            {items.map((entry) => (
              <Cell
                key={entry.id}
                fill={entry.color}
                stroke={selectedId === entry.id ? '#1f2937' : 'none'}
                strokeWidth={selectedId === entry.id ? 2 : 0}
              />
            ))}
          </Pie>
          <Tooltip
            formatter={(value: number) => [`¥${value.toLocaleString()}`, '金額']}
            contentStyle={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e5e7eb' }}
          />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
}

import { ExpenseItem } from './types';
import './index.css';

interface ExpenseListProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (item: ExpenseItem) => void;
}

export default function ExpenseList({ items = [], selectedId, onSelect }: ExpenseListProps) {
  return (
    <div className="list-container">
      <ul className="expense-list">
        {items.map((item) => {
          const isSelected = selectedId === item.id;
          return (
            <li
              key={item.id}
              className={`expense-item ${isSelected ? 'active' : ''}`}
              style={{ borderLeftColor: item.color }}
              onClick={() => onSelect(item)}
            >
              <span>{item.category}</span>
              <strong>¥{item.amount.toLocaleString()}</strong>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useState } from 'react';
import { ExpenseItem } from './types';
import ExpenseChart from './ExpenseChart';
import ExpenseList from './ExpenseList';
import './index.css';

const initialItems: ExpenseItem[] = [
  { id: '1', category: '食費', amount: 45000, color: '#4f46e5', memo: '外食やスーパーでの食材購入費など' },
  { id: '2', category: '家賃', amount: 80000, color: '#3b82f6', memo: '毎月のマンション家賃（共益費込）' },
  { id: '3', category: '光熱費', amount: 12000, color: '#06b6d4', memo: '電気・ガス・水道の合算' },
  { id: '4', category: '通信費', amount: 8000, color: '#10b981', memo: 'スマホ料金および自宅のインターネット回線' },
  { id: '5', category: '娯楽', amount: 15000, color: '#f59e0b', memo: '映画、書籍、趣味に関する費用' },
  { id: '6', category: '交通費', amount: 10000, color: '#ef4444', memo: '通勤定期や休日の電車・バス代' },
];

export default function App() {
  const [items] = useState<ExpenseItem[]>(initialItems);
  const [selectedId, setSelectedId] = useState<string | null>(initialItems[0]?.id || null);

  const selectedItem = items.find((item) => item.id === selectedId) || items[0];
  const totalAmount = items.reduce((sum, item) => sum + item.amount, 0);

  const handleSelect = (item: ExpenseItem) => {
    setSelectedId(item.id);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>家計簿ダッシュボード</h1>
        <div className="total-amount">
          総支出: ¥{totalAmount.toLocaleString()}
        </div>
      </header>

      <main className="main-content">
        <div className="card">
          <h2 className="section-title">支出内訳グラフ</h2>
          <ExpenseChart items={items} selectedId={selectedId} onSelect={handleSelect} />
        </div>

        <div className="card">
          <h2 className="section-title">項目一覧</h2>
          <ExpenseList items={items} selectedId={selectedId} onSelect={handleSelect} />
        </div>
      </main>

      {selectedItem && (
        <div className="detail-card">
          <h3>詳細情報: {selectedItem.category}</h3>
          <p>金額: ¥{selectedItem.amount.toLocaleString()}</p>
          <p>メモ: {selectedItem.memo}</p>
        </div>
      )}
    </div>
  );
}
